-- Stored procedures for the sample. POST_TRAN is in COBOL.
CREATE PROCEDURE BANK.POST_TRAN
  (IN CUST_ID INTEGER, INOUT AMOUNT DECIMAL(9, 2))
  LANGUAGE COBOL
  EXTERNAL NAME POSTTRN
  PARAMETER STYLE GENERAL
  EXTERNAL SECURITY DB2
  DYNAMIC RESULT SETS 1;

CREATE PROCEDURE BANK.SAMPSUB ()
  LANGUAGE COBOL
  EXTERNAL;

CREATE OR REPLACE PROCEDURE BANK.PURGE_AUDIT (IN DAYS INTEGER)
  LANGUAGE SQL
  EXTERNAL SECURITY DB2
BEGIN
  DECLARE C1 CURSOR FOR SELECT ID FROM BANK.AUDIT_LOG FOR UPDATE OF ID;
  DELETE FROM BANK.AUDIT_LOG WHERE AGE > DAYS;
  INSERT INTO BANK.PURGE_HIST SELECT * FROM BANK.AUDIT_ARCH;
  CALL BANK.POST_TRAN(1, 0);
END#
